			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg100_e - ntc_rg100 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg100:
;## ntc_font
; 8x8 font buffer, chars 32-126, 8 bytes each, bit 7 = leftmost pixel.
; The platform fills it at start: the CPC copies its own font from the
; lower ROM (#3900), so text looks like the CPC's.
; glyph for char c = ntc_font + (c - 32) * 8
ntc_font:		ds 95 * 8

; ============================================================
; Platform class capabilities
; ============================================================

ntc_rg100_e:
			IF ($ < 49152) && (ntc_rg101_e - ntc_rg101 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg101_e - ntc_rg101 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg101_e - ntc_rg101 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg101:
;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			jr z, ntc_bs_ok		; (the stack just under them: CP/M's ntc_cpmstack = their start)
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "GURU 001", 0

ntc_rg101_e:
			IF ($ < 49152) && (ntc_rg102_e - ntc_rg102 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg102_e - ntc_rg102 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg102_e - ntc_rg102 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg102:
;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_smode:		db 1			; screen mode (0, 1: 40 columns, 2: 80)
ntc_sinit:		db 0			; 1 once the tilemap is set up
ntc_scols:		db 40			; columns
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line
ntc_klink:		dw 0			; return for ntc_plat_getkey
ntc_kidx:		db 0			; key index found by the scan
ntc_kcur:		ds 8			; the 8 half rows this scan (0 = pressed)
ntc_kprev:		db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF
ntc_irqset:		db 0			; 1 = our interrupt handler is at #38
ntc_irqold:		ds 3			; the 3 bytes it replaced
ntc_irqhl:		dw 0			; handler scratch
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
ntc_zxvs:		db 0			; 1: this interrupt is a frame's first (line 0 passed: to ntc_isl_tick in C)
ntc_zxline:		dw 0			; the raster line the line interrupt is set to
ntc_zxsel:		db 0			; the NextReg selected (#243B) by code interrupts can get into: the
								; handler selects it again after its own (store it, then select)
ntc_zxl2:		db 0			; 1 = Layer 2 is on (Graphics); Mode turns it off
ZXN_MAP			equ #E000		; the tilemap (bank 5 + #2000: NextReg #6E = #20)
ZXN_TILES		equ #EC00		; its characters (bank 5 + #2C00: NextReg #6F = #2C)
ZXN_ROWS		equ 32
ZXN_PAPER		equ #02			; RRRGGGBB: blue
ZXN_INK			equ #FC			; yellow

ntc_rg102_e:
			IF ($ < 49152) && (ntc_rg103_e - ntc_rg103 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg103_e - ntc_rg103 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg103_e - ntc_rg103 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg103:
;## ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_putc - A = character 32-126 (others print as ?), draw it
; ------------------------------------------------------------
ntc_plat_putc:
			cp 32
			jr c, ntc_pc_bad
			cp 127
			jr c, ntc_zx_put
ntc_pc_bad:
			ld a, '?'
			jr ntc_zx_put

; ------------------------------------------------------------
; ntc_plat_putglyph - DE = an 8 byte glyph in ntc_font (ZOSCII text): that
; character at the cursor, the cursor on (a glyph not in ntc_font: ?)
; ------------------------------------------------------------
ntc_plat_putglyph:
			ld hl, -ntc_font
			add hl, de				; HL = the glyph's offset: 0 .. 95 * 8 - 1
			ld a, h
			cp (95 * 8) / 256
			jr c, ntc_pg_in
			jr nz, ntc_pc_bad
			ld a, l
			cp (95 * 8) & 255
			jr nc, ntc_pc_bad
ntc_pg_in:
			srl h
			rr l
			srl h
			rr l
			srl h
			rr l
			ld a, l
			add a, 32
			; fall into ntc_zx_put

; A = a character code: into the tilemap at the cursor (its tile), the cursor on
ntc_zx_put:
			ld c, a
			ld a, (ntc_cury)		; HL = ZXN_MAP + row * columns + column
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de				; row * 40
			ld a, (ntc_scols)
			cp 80
			jr nz, $+3
			add hl, hl				; row * 80
			ld a, (ntc_curx)
			ld e, a
			ld d, ZXN_MAP / 256		; (ZXN_MAP's low byte is 0)
			add hl, de
			ld (hl), c
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pg_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pg_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do

; ------------------------------------------------------------
; ntc_plat_newline - column 0, next row, scroll at the bottom. Straight
; after a wrap at the last column it does nothing (as the firmware does)
; ------------------------------------------------------------
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp ZXN_ROWS
			jp nc, ntc_plat_scroll
			ld (ntc_cury), a
			jp (ix)

ntc_rg103_e:
			IF ($ < 49152) && (ntc_rg104_e - ntc_rg104 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg104_e - ntc_rg104 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg104_e - ntc_rg104 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg104:
;## ntc_plat_backspace @unit ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_backspace - cursor back one and blank that cell
; ------------------------------------------------------------
ntc_plat_backspace:
			xor a
			ld (ntc_wrapped), a
			ld a, (ntc_curx)
			or a
			jr nz, ntc_bs_col
			ld a, (ntc_cury)
			or a
			jr z, ntc_bs_none
			dec a
			ld (ntc_cury), a
			ld a, (ntc_scols)
ntc_bs_col:
			dec a
			ld (ntc_curx), a
			ld a, (ntc_cury)		; HL = ZXN_MAP + row * columns + column
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de				; row * 40
			ld a, (ntc_scols)
			cp 80
			jr nz, $+3
			add hl, hl				; row * 80
			ld a, (ntc_curx)
			ld e, a
			ld d, ZXN_MAP / 256		; (ZXN_MAP's low byte is 0)
			add hl, de
			ld (hl), ' '
ntc_bs_none:
			jp (ix)

ntc_rg104_e:
			IF ($ < 49152) && (ntc_rg105_e - ntc_rg105 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg105_e - ntc_rg105 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg105_e - ntc_rg105 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg105:
;## ntc_plat_mode @unit ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_mode - A = mode: 0, 1 = 40 x 32, 2 (3) = 80 x 32. The first time the
; tilemap is set up (font, palette, its registers); then its width, clear screen
; ------------------------------------------------------------
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			ld (ntc_smode), a
			ld a, (ntc_sinit)
			or a
			jp nz, ntc_md_set
			inc a
			ld (ntc_sinit), a
			ld hl, ntc_zxfont		; the font to ntc_font (ZOSCII's glyphs point there)
			ld de, ntc_font
			ld bc, 95 * 8
			ldir
			ld hl, ZXN_TILES		; the tiles: 0-31 and 127-255 blank, 32-126 the font
			ld de, ZXN_TILES + 1
			ld bc, 256 * 8 - 1
			ld (hl), 0
			ldir
			ld hl, ntc_zxfont
			ld de, ZXN_TILES + 32 * 8
			ld bc, 95 * 8
			ldir
			ld bc, #243B
			ld a, #43
			out (c), a
			inc b
			ld a, #30
			out (c), a
			dec b					; palette: the tilemap's first, index 0 paper, 1 ink
			ld bc, #243B
			ld a, #40
			out (c), a
			inc b
			ld a, 0
			out (c), a
			dec b
			ld a, #41
			out (c), a
			inc b
			ld a, ZXN_PAPER
			out (c), a
			ld a, ZXN_INK
			out (c), a				; (the index moves on by itself)
			ld bc, #243B
			ld a, #6C
			out (c), a
			inc b
			ld a, 0
			out (c), a
			dec b					; every tile's attribute: palette offset 0
			ld bc, #243B
			ld a, #6E
			out (c), a
			inc b
			ld a, #20
			out (c), a
			dec b					; the map at bank 5 + #2000
			ld bc, #243B
			ld a, #6F
			out (c), a
			inc b
			ld a, #2C
			out (c), a
			dec b					; the tiles at bank 5 + #2C00
			ld bc, #243B
			ld bc, #243B
			ld a, #2F
			out (c), a
			inc b
			ld a, 0
			out (c), a
			dec b					; no scroll
			ld bc, #243B
			ld a, #30
			out (c), a
			inc b
			ld a, 0
			out (c), a
			dec b
			ld bc, #243B
			ld a, #31
			out (c), a
			inc b
			ld a, 0
			out (c), a
			dec b
			ld bc, #243B
			ld a, #1C
			out (c), a
			inc b
			ld a, 8
			out (c), a
			dec b					; the tilemap's clip window: the whole of it
			ld a, #1B
			out (c), a
			inc b
			xor a
			out (c), a
			ld a, 159
			out (c), a
			xor a
			out (c), a
			dec a
			out (c), a
ntc_md_set:
			ld hl, ntc_md_regs		; the text screen alone: Layer 2 off (Graphics turns it on), the
			ld bc, #243B			; ULA on, the tilemap opaque, bank 5's first page at #C000
			ld e, 9
ntc_md_rg:
			ld a, (hl)
			inc hl
			out (c), a
			inc b
			ld a, (hl)
			inc hl
			out (c), a
			dec b
			dec e
			jr nz, ntc_md_rg
			xor a
			ld (ntc_zxl2), a
			ld a, (ntc_smode)
			cp 2
			ld a, 40
			ld e, #A9				; tilemap on, 40 x 32, no attributes, text mode, over the ULA
			jr nz, ntc_md_40
			ld a, 80
			ld e, #E9				; the same, 80 x 32
ntc_md_40:
			ld (ntc_scols), a
			ld bc, #243B
			ld a, #6B
			out (c), a
			inc b
			ld a, e
			out (c), a
			jp ntc_plat_cls

; NextReg, value: Layer 2 off, the ULA from bank 5, no Timex mode (#69); sprites off, the
; layers' order as at reset (#15); the ULA on, no ULA+ (#68); the tilemap's index 15
; transparent - its paper (0) not (#4C); page 10 at #C000 (#56: Graphics draws there); the
; tilemap's paper its colour again (Graphics makes it see-through)
ntc_md_regs:	db #69, 0, #15, 0, #68, 0, #4C, #0F, #56, 10, #57, 11, #43, #30, #40, 0, #41, ZXN_PAPER

; the font: the Amstrad CPC's own (its lower ROM's characters 32-126, as the CPC platforms
; read from the ROM; 20261116-6: this table held font8x8_basic until then - a bug) - 8 bytes
; each, bit 7 the leftmost pixel
ntc_zxfont:
			db #00, #00, #00, #00, #00, #00, #00, #00	; 32 
			db #18, #18, #18, #18, #18, #00, #18, #00	; 33 !
			db #6C, #6C, #6C, #00, #00, #00, #00, #00	; 34 "
			db #6C, #6C, #FE, #6C, #FE, #6C, #6C, #00	; 35 #
			db #18, #3E, #58, #3C, #1A, #7C, #18, #00	; 36 $
			db #00, #C6, #CC, #18, #30, #66, #C6, #00	; 37 %
			db #38, #6C, #38, #76, #DC, #CC, #76, #00	; 38 &
			db #18, #18, #30, #00, #00, #00, #00, #00	; 39 '
			db #0C, #18, #30, #30, #30, #18, #0C, #00	; 40 (
			db #30, #18, #0C, #0C, #0C, #18, #30, #00	; 41 )
			db #00, #66, #3C, #FF, #3C, #66, #00, #00	; 42 *
			db #00, #18, #18, #7E, #18, #18, #00, #00	; 43 +
			db #00, #00, #00, #00, #00, #18, #18, #30	; 44 ,
			db #00, #00, #00, #7E, #00, #00, #00, #00	; 45 -
			db #00, #00, #00, #00, #00, #18, #18, #00	; 46 .
			db #06, #0C, #18, #30, #60, #C0, #80, #00	; 47 /
			db #7C, #C6, #CE, #D6, #E6, #C6, #7C, #00	; 48 0
			db #18, #38, #18, #18, #18, #18, #7E, #00	; 49 1
			db #3C, #66, #06, #3C, #60, #66, #7E, #00	; 50 2
			db #3C, #66, #06, #1C, #06, #66, #3C, #00	; 51 3
			db #1C, #3C, #6C, #CC, #FE, #0C, #1E, #00	; 52 4
			db #7E, #62, #60, #7C, #06, #66, #3C, #00	; 53 5
			db #3C, #66, #60, #7C, #66, #66, #3C, #00	; 54 6
			db #7E, #66, #06, #0C, #18, #18, #18, #00	; 55 7
			db #3C, #66, #66, #3C, #66, #66, #3C, #00	; 56 8
			db #3C, #66, #66, #3E, #06, #66, #3C, #00	; 57 9
			db #00, #00, #18, #18, #00, #18, #18, #00	; 58 :
			db #00, #00, #18, #18, #00, #18, #18, #30	; 59 ;
			db #0C, #18, #30, #60, #30, #18, #0C, #00	; 60 <
			db #00, #00, #7E, #00, #00, #7E, #00, #00	; 61 =
			db #60, #30, #18, #0C, #18, #30, #60, #00	; 62 >
			db #3C, #66, #66, #0C, #18, #00, #18, #00	; 63 ?
			db #7C, #C6, #DE, #DE, #DE, #C0, #7C, #00	; 64 @
			db #18, #3C, #66, #66, #7E, #66, #66, #00	; 65 A
			db #FC, #66, #66, #7C, #66, #66, #FC, #00	; 66 B
			db #3C, #66, #C0, #C0, #C0, #66, #3C, #00	; 67 C
			db #F8, #6C, #66, #66, #66, #6C, #F8, #00	; 68 D
			db #FE, #62, #68, #78, #68, #62, #FE, #00	; 69 E
			db #FE, #62, #68, #78, #68, #60, #F0, #00	; 70 F
			db #3C, #66, #C0, #C0, #CE, #66, #3E, #00	; 71 G
			db #66, #66, #66, #7E, #66, #66, #66, #00	; 72 H
			db #7E, #18, #18, #18, #18, #18, #7E, #00	; 73 I
			db #1E, #0C, #0C, #0C, #CC, #CC, #78, #00	; 74 J
			db #E6, #66, #6C, #78, #6C, #66, #E6, #00	; 75 K
			db #F0, #60, #60, #60, #62, #66, #FE, #00	; 76 L
			db #C6, #EE, #FE, #FE, #D6, #C6, #C6, #00	; 77 M
			db #C6, #E6, #F6, #DE, #CE, #C6, #C6, #00	; 78 N
			db #38, #6C, #C6, #C6, #C6, #6C, #38, #00	; 79 O
			db #FC, #66, #66, #7C, #60, #60, #F0, #00	; 80 P
			db #38, #6C, #C6, #C6, #DA, #CC, #76, #00	; 81 Q
			db #FC, #66, #66, #7C, #6C, #66, #E6, #00	; 82 R
			db #3C, #66, #60, #3C, #06, #66, #3C, #00	; 83 S
			db #7E, #5A, #18, #18, #18, #18, #3C, #00	; 84 T
			db #66, #66, #66, #66, #66, #66, #3C, #00	; 85 U
			db #66, #66, #66, #66, #66, #3C, #18, #00	; 86 V
			db #C6, #C6, #C6, #D6, #FE, #EE, #C6, #00	; 87 W
			db #C6, #6C, #38, #38, #6C, #C6, #C6, #00	; 88 X
			db #66, #66, #66, #3C, #18, #18, #3C, #00	; 89 Y
			db #FE, #C6, #8C, #18, #32, #66, #FE, #00	; 90 Z
			db #3C, #30, #30, #30, #30, #30, #3C, #00	; 91 [
			db #C0, #60, #30, #18, #0C, #06, #02, #00	; 92 \
			db #3C, #0C, #0C, #0C, #0C, #0C, #3C, #00	; 93 ]
			db #18, #3C, #7E, #18, #18, #18, #18, #00	; 94 ^
			db #00, #00, #00, #00, #00, #00, #00, #FF	; 95 _
			db #30, #18, #0C, #00, #00, #00, #00, #00	; 96 `
			db #00, #00, #78, #0C, #7C, #CC, #76, #00	; 97 a
			db #E0, #60, #7C, #66, #66, #66, #DC, #00	; 98 b
			db #00, #00, #3C, #66, #60, #66, #3C, #00	; 99 c
			db #1C, #0C, #7C, #CC, #CC, #CC, #76, #00	; 100 d
			db #00, #00, #3C, #66, #7E, #60, #3C, #00	; 101 e
			db #1C, #36, #30, #78, #30, #30, #78, #00	; 102 f
			db #00, #00, #3E, #66, #66, #3E, #06, #7C	; 103 g
			db #E0, #60, #6C, #76, #66, #66, #E6, #00	; 104 h
			db #18, #00, #38, #18, #18, #18, #3C, #00	; 105 i
			db #06, #00, #0E, #06, #06, #66, #66, #3C	; 106 j
			db #E0, #60, #66, #6C, #78, #6C, #E6, #00	; 107 k
			db #38, #18, #18, #18, #18, #18, #3C, #00	; 108 l
			db #00, #00, #6C, #FE, #D6, #D6, #C6, #00	; 109 m
			db #00, #00, #DC, #66, #66, #66, #66, #00	; 110 n
			db #00, #00, #3C, #66, #66, #66, #3C, #00	; 111 o
			db #00, #00, #DC, #66, #66, #7C, #60, #F0	; 112 p
			db #00, #00, #76, #CC, #CC, #7C, #0C, #1E	; 113 q
			db #00, #00, #DC, #76, #60, #60, #F0, #00	; 114 r
			db #00, #00, #3C, #60, #3C, #06, #7C, #00	; 115 s
			db #30, #30, #7C, #30, #30, #36, #1C, #00	; 116 t
			db #00, #00, #66, #66, #66, #66, #3E, #00	; 117 u
			db #00, #00, #66, #66, #66, #3C, #18, #00	; 118 v
			db #00, #00, #C6, #D6, #D6, #FE, #6C, #00	; 119 w
			db #00, #00, #C6, #6C, #38, #6C, #C6, #00	; 120 x
			db #00, #00, #66, #66, #66, #3E, #06, #7C	; 121 y
			db #00, #00, #7E, #4C, #18, #32, #7E, #00	; 122 z
			db #0E, #18, #18, #70, #18, #18, #0E, #00	; 123 {
			db #18, #18, #18, #18, #18, #18, #18, #00	; 124 |
			db #70, #18, #18, #0E, #18, #18, #70, #00	; 125 }
			db #76, #DC, #00, #00, #00, #00, #00, #00	; 126 ~

ntc_rg105_e:
			IF ($ < 49152) && (ntc_rg106_e - ntc_rg106 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg106_e - ntc_rg106 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg106_e - ntc_rg106 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg106:
;## ntc_plat_scroll ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_scroll - move rows 1-31 up one, clear row 31
; ------------------------------------------------------------
ntc_plat_scroll:
			ld a, ZXN_ROWS - 1
			ld (ntc_cury), a
			ld a, (ntc_scols)
			ld c, a
			ld b, 0					; BC = a row
			ld hl, ZXN_MAP
			add hl, bc
			ld de, ZXN_MAP
			cp 80
			ld bc, (ZXN_ROWS - 1) * 40
			jr nz, ntc_sc_40
			ld bc, (ZXN_ROWS - 1) * 80
ntc_sc_40:
			ldir					; DE = the last row
			ld h, d
			ld l, e
			ld (hl), ' '
			inc de
			ld c, a
			dec c
			ld b, 0
			ldir
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_cls - the whole tilemap spaces, cursor home
; ------------------------------------------------------------
ntc_plat_cls:
			ld hl, ZXN_MAP
			ld de, ZXN_MAP + 1
			ld bc, ZXN_ROWS * 80 - 1
			ld (hl), ' '
			ldir
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

ntc_rg106_e:
			IF ($ < 49152) && (ntc_rg107_e - ntc_rg107 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg107_e - ntc_rg107 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg107_e - ntc_rg107 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg107:
;## ntc_plat_key ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_scankey - A = ASCII of a key pressed since the last scan,
; 0 if none
; ------------------------------------------------------------
ntc_plat_scankey:
			ld hl, ntc_kcur
			ld b, #FE				; half row 0 (address line A8 low) ... 7 (A15)
ntc_ks_line:
			ld c, #FE
			in a, (c)
			or #E0					; (bits 5-7: no keys)
			ld (hl), a
			inc hl
			rlc b
			jr c, ntc_ks_line		; (B's 0 bit moves up: done after A15)
			ld a, #FF
			ld (ntc_kidx), a
			ld hl, ntc_kcur
			ld de, ntc_kprev
			ld iy, ntc_kign
			ld bc, #0800			; B = 8 half rows, C = key index (half row * 8 + bit)
ntc_ks_find:
			ld a, (ntc_kidx)
			inc a
			jr nz, ntc_ks_next
			ld a, (hl)
			cpl
			ex de, hl
			and (hl)				; pressed now, released last scan
			ex de, hl
			and (iy+0)				; not Caps Shift / Symbol Shift
			jr z, ntc_ks_next
ntc_ks_bit:
			rrca
			jr c, ntc_ks_got
			inc c
			jr ntc_ks_bit
ntc_ks_got:
			ld a, c
			ld (ntc_kidx), a
ntc_ks_next:
			ld a, c
			and #F8
			add a, 8
			ld c, a
			inc hl
			inc de
			inc iy
			djnz ntc_ks_find
			ld hl, ntc_kcur
			ld de, ntc_kprev
			ld bc, 8
			ldir
			ld a, (ntc_kidx)
			cp #FF
			jr z, ntc_ks_none
			ld e, a
			ld d, 0
			ld hl, ntc_keymapy		; Symbol Shift (half row 7 bit 1) first
			ld a, (ntc_kcur + 7)
			bit 1, a
			jr z, ntc_ks_map
			ld hl, ntc_keymapc		; then Caps Shift (half row 0 bit 0)
			ld a, (ntc_kcur)
			bit 0, a
			jr z, ntc_ks_map
			ld hl, ntc_keymap
ntc_ks_map:
			add hl, de
			ld a, (hl)
			jp (ix)
ntc_ks_none:
			xor a
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_getkey - wait for a key press, A = ASCII
; ------------------------------------------------------------
ntc_plat_getkey:
			ld (ntc_klink), ix
ntc_gk_scan:
			ld ix, ntc_gk_back
			jp ntc_plat_scankey
ntc_gk_back:
			or a
			jr nz, ntc_gk_done
			ld a, (ntc_nmode)		; normal mode: interrupts in while waiting
			or a
			jr z, ntc_gk_wait
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_gk_wait:
			ld bc, 7000				; about 6ms between scans at 28MHz (debounce)
ntc_gk_delay:
			dec bc
			ld a, b
			or c
			jr nz, ntc_gk_delay
			di
			ld a, (ntc_nmode)
			or a
			jr z, ntc_gk_scan
			ld sp, (ntc_ip)
			jr ntc_gk_scan
ntc_gk_done:
			ld ix, (ntc_klink)
			jp (ix)

; keys that never count as a press on their own (Caps Shift, Symbol Shift)
ntc_kign:		db #FE, #FF, #FF, #FF, #FF, #FF, #FF, #FD

; half row 0-7, bit 0-4 -> ASCII (0 = nothing); 8 a half row, 5-7 unused
; 0 Caps Z X C V   1 A S D F G   2 Q W E R T   3 1 2 3 4 5
; 4 0 9 8 7 6      5 P O I U Y  6 Enter L K J H   7 Space Symbol M N B
ntc_keymap:
			db 0, "z", "x", "c", "v", 0, 0, 0
			db "a", "s", "d", "f", "g", 0, 0, 0
			db "q", "w", "e", "r", "t", 0, 0, 0
			db "1", "2", "3", "4", "5", 0, 0, 0
			db "0", "9", "8", "7", "6", 0, 0, 0
			db "p", "o", "i", "u", "y", 0, 0, 0
			db 13, "l", "k", "j", "h", 0, 0, 0
			db " ", 0, "m", "n", "b", 0, 0, 0
ntc_keymapc:								; Caps Shift: capitals; + 0 DEL, + Space Break; the cursor
			db 0, "Z", "X", "C", "V", 0, 0, 0		; keys (Caps + 5-8) the CPC firmware's codes: up 240,
			db "A", "S", "D", "F", "G", 0, 0, 0		; down 241, left 242, right 243
			db "Q", "W", "E", "R", "T", 0, 0, 0
			db 0, 0, 0, 0, 242, 0, 0, 0			; (Edit, Caps Lock, True / Inverse Video: nothing), cursor left
			db 127, 0, 243, 240, 241, 0, 0, 0		; (Graphics: nothing), cursor right / up / down
			db "P", "O", "I", "U", "Y", 0, 0, 0
			db 13, "L", "K", "J", "H", 0, 0, 0
			db 27, 0, "M", "N", "B", 0, 0, 0
ntc_keymapy:								; Symbol Shift: the symbols on the keys (+ the 128's ~ | \ { } [ ])
			db 0, ":", 0, "?", "/", 0, 0, 0		; (X: pound)
			db "~", "|", 92, "{", "}", 0, 0, 0
			db 0, 0, 0, "<", ">", 0, 0, 0		; (Q, W, E: <= <> >=)
			db "!", "@", "#", "$", "%", 0, 0, 0
			db "_", ")", "(", 39, "&", 0, 0, 0
			db 34, ";", 0, "]", "[", 0, 0, 0		; (I: copyright)
			db 13, "=", "+", "-", "^", 0, 0, 0
			db " ", 0, ".", ",", "*", 0, 0, 0

ntc_rg107_e:
			IF ($ < 49152) && (ntc_rg108_e - ntc_rg108 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg108_e - ntc_rg108 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg108_e - ntc_rg108 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg108:
;## ntc_plat_frame ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_frame - wait for the end of the display (raster line 192: the
; bottom border starts). Normal mode: interrupts in while waiting
; ------------------------------------------------------------
ntc_plat_frame:
			ld (ntc_klink), ix		; (ntc_klink: the return - IX runs ntc_fr_line)
			ld a, (ntc_nmode)
			or a
			jr z, ntc_fr_go
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_fr_go:
			ld bc, #243B
ntc_fr_out:						; first out of lines 192 and on (the border, the sync)
			ld ix, ntc_fr_out2
			jr ntc_fr_line
ntc_fr_out2:
			jr nz, ntc_fr_out
ntc_fr_in:						; then wait for line 192
			ld ix, ntc_fr_in2
			jr ntc_fr_line
ntc_fr_in2:
			jr z, ntc_fr_in
			jr ntc_fr_at
; the raster line (NextReg #1E: its bit 8, #1F: bits 0-7), its two halves read
; again until bit 8 is the same both times (line 255 to 256 between them reads
; as 0): NZ = line 192 or more. Back to IX; keeps BC (#243B)
ntc_fr_line:
			ld a, #1E
			ld (ntc_zxsel), a		; (interrupts are in: the handler selects it again)
			out (c), a
			inc b
			in d, (c)
			dec b
			ld a, #1F
			ld (ntc_zxsel), a
			out (c), a
			inc b
			in e, (c)
			dec b
			ld a, #1E
			ld (ntc_zxsel), a
			out (c), a
			inc b
			in a, (c)
			dec b
			cp d
			jr nz, ntc_fr_line
			ld d, a
		IF NTC_ZXIRQ					; (the interrupt handler is in the program: normal mode)
			ld a, (ntc_irqset)		; the line interrupt's chain: a pulse that came while interrupts
			or a					; were off was lost - the wait here is where a program with long
			jr z, ntc_fr_lok		; stretches of them lets interrupts in, so see that the raster has
			ld a, d					; not passed the line set without its interrupt (the same line in
			and 1					; the same stretch every frame: Frame paces a program to the
			ld h, a					; frame, so a lost one would stay lost): then the handler is
			ld l, e					; called, to count the ticks missed and set the line ahead
			push de
			ex de, hl
			ld hl, (ntc_zxline)
			or a
			sbc hl, de				; the line set - now (mod 312): 0-56 = ahead, its pulse comes (the
			jr nc, ntc_fr_l1		; chain sets the next line 52 on at most); more = passed, lost
			ld de, 312
			add hl, de
ntc_fr_l1:
			ld de, -57
			add hl, de
			jr nc, ntc_fr_l2
			di
			call ntc_irq			; (ends with ei: as its interrupt would)
ntc_fr_l2:
			pop de
			ld bc, #243B
ntc_fr_lok:
		ENDIF
			ld a, d
			rra
			jr c, ntc_fr_lnz		; 256 and on
			ld a, e
			cp 192
			ccf
			sbc a, a				; #FF: 192-255, 0: below
			jp (ix)
ntc_fr_lnz:
			or 1
			jp (ix)
ntc_fr_at:
			di
			ld a, (ntc_nmode)
			or a
			jr z, ntc_fr_done
			ld sp, (ntc_ip)
ntc_fr_done:
			ld ix, (ntc_klink)
			jp (ix)

ntc_rg108_e:
			IF ($ < 49152) && (ntc_rg109_e - ntc_rg109 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg109_e - ntc_rg109 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg109_e - ntc_rg109 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg109:
;## ntc_plat_ticks ntc_data
; ------------------------------------------------------------
; ntc_plat_ticks - HL = interrupt count (300 a second, normal mode)
; ------------------------------------------------------------
ntc_plat_ticks:
			ld hl, (ntc_ticks)
			jp (ix)

ntc_rg109_e:
			IF ($ < 49152) && (ntc_rg110_e - ntc_rg110 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg110_e - ntc_rg110 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg110_e - ntc_rg110 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg110:
;## ntc_plat_irq ntc_plat_data ntc_data ntc_plat_irqh @shared
; ------------------------------------------------------------
; ntc_plat_irqon - put the interrupt handler at #38 (IM 1: the stub set it) and
; start the line interrupt at raster line 0, the ULA's frame interrupt off
; (NextReg #22: bit 2 the ULA's off, bit 1 the line interrupt on, bit 0 the
; line's bit 8; #23 its bits 0-7). The handler moves it on 52 lines each time
; ------------------------------------------------------------
ntc_plat_irqon:
			ld hl, (#0038)
			ld (ntc_irqold), hl
			ld a, (#003A)
			ld (ntc_irqold + 2), a
			ld a, #C3			; jp ntc_irq
			ld (#0038), a
			ld hl, ntc_irq
			ld (#0039), hl
			ld hl, 0
			ld (ntc_zxline), hl
			ld bc, #243B
			ld a, #23
			out (c), a
			inc b
			xor a
			out (c), a
			dec b
			ld a, #22
			out (c), a
			inc b
			ld a, 6
			out (c), a
			ld a, 1
			ld (ntc_irqset), a
			jp (ix)

ntc_rg110_e:
			IF ($ < 49152) && (ntc_rg111_e - ntc_rg111 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg111_e - ntc_rg111 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg111_e - ntc_rg111 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg111:
;## ntc_plat_irqh ntc_plat_data ntc_data @shared
; the handler: runs on the real stack, between keywords. The line interrupt, every 52 raster
; lines - 6 a frame of 312 lines, 300 a second, as the CPC's: counts the ticks and sets the
; next one. The Next's INT is a pulse (32 T at 3.5MHz), not held: a program with interrupts
; off while the line passes (a long stretch between two Frame waits, say) misses that one.
; So the next line is not simply this one + 52: the raster is read (#1E, #1F) and every 52
; line step from the line this interrupt was set for up to the raster now counts as a tick
; (the ones missed included: the clock keeps 300 a second), and the next interrupt is set at
; the step after - never at a line the raster has passed, which would leave the chain dead
; until it came round, or for ever if the program is always off at that line. The step at
; line 0 is a frame's first (ntc_zxvs 1 for the interrupt classes' counting: it is counted
; even when it was missed). AF goes to AF', HL to RAM, the other registers are kept.
ntc_irq:
			ex af, af'
			ld (ntc_irqhl), hl
			push bc
			push de
			ld bc, #243B
ntc_irq_rd:						; DE = the raster line now (#1E bit 8, #1F: read again until bit 8 holds)
			ld a, #1E
			out (c), a
			inc b
			in d, (c)
			dec b
			ld a, #1F
			out (c), a
			inc b
			in e, (c)
			dec b
			ld a, #1E
			out (c), a
			inc b
			in a, (c)
			dec b
			cp d
			jr nz, ntc_irq_rd
			and 1
			ld d, a
			ld hl, (ntc_zxline)		; the line this interrupt was set for
			ld a, h
			or l
			ld a, 0
			jr nz, ntc_irq_nf
			inc a
ntc_irq_nf:
			ld (ntc_zxvs), a		; 1: line 0, a frame's first (so far: a wrap below sets it too)
			ex de, hl				; HL = now, DE = set for
			or a
			sbc hl, de				; HL = now - set for
			jr nc, ntc_irq_fw
			ld bc, 16				; a little before it (the pulse comes as the line before ends): 0
			add hl, bc
			jr c, ntc_irq_z
			ld bc, 312 - 16			; else the raster wrapped: + 312
			add hl, bc
			jr ntc_irq_fw
ntc_irq_z:
			ld hl, 0
ntc_irq_fw:
			ld c, 1					; C = the ticks: 1 + (now - set for) / 52
			ld b, 0					; (BC = 52 * the ticks past the first, the step to the next line)
ntc_irq_dv:
			ld a, l
			sub 52
			ld l, a
			ld a, h
			sbc a, 0
			ld h, a
			jr c, ntc_irq_dd
			inc c
			ld a, c
			cp 7					; (6 at most: a frame)
			jr c, ntc_irq_dv
			dec c
ntc_irq_dd:
			ld a, c
			ld (ntc_irqn), a
			ld hl, (ntc_ticks)
			ld b, 0
			add hl, bc
			ld (ntc_ticks), hl
			ld hl, 0				; the next line: set for + 52 * the ticks (mod 312)
			ld bc, 52
			ld a, (ntc_irqn)
ntc_irq_st:
			add hl, bc
			dec a
			jr nz, ntc_irq_st
			add hl, de
			ld bc, -312
			add hl, bc
			jr c, ntc_irq_wrp		; past the last line (312 and on): wrapped - line 0 was passed
			sbc hl, bc				; (carry clear: back to the line)
			jr ntc_irq_wr
ntc_irq_wrp:
			ld a, (ntc_irqn)		; the wrap: the step at line 0 was one of these ticks, unless it is
			dec a					; the next one (the only tick was the one set for: HL = 0 now)
			jr nz, ntc_irq_wv
			ld a, h
			or l
			jr z, ntc_irq_wr
ntc_irq_wv:
			ld a, 1
			ld (ntc_zxvs), a
ntc_irq_wr:
			ld (ntc_zxline), hl
			ld bc, #243B
			ld a, #23
			out (c), a
			inc b
			out (c), l
			dec b
			ld a, #22
			out (c), a
			inc b
			ld a, h
			or 6					; the ULA's interrupt off, the line interrupt on
			out (c), a
			dec b
			ld a, (ntc_zxsel)		; the NextReg the code it came in on had selected
			out (c), a
			pop de
			pop bc
			ld a, (ntc_hookon)	; an Interrupt hook: run it at the next safe point
			or a
			jr z, ntc_irq_nohook
			ld (ntc_hookpend), a
ntc_irq_nohook:
			ld hl, (ntc_irqv)		; interrupt classes (Option Class Interrupt): count them - once
			ld a, h					; a tick (the missed ones too: the frame's first among them last,
			or l					; so the classes see it in the same order as the ticks came)
			jr z, ntc_irq_nocl
			push bc
			ld a, (ntc_irqn)
			ld b, a
ntc_irq_cl:
			ld c, 0					; C = 1: a frame's first (ntc_isl_tick reads it on zxn)
			dec b
			jr nz, ntc_irq_cl1
			ld a, (ntc_zxvs)
			ld c, a
ntc_irq_cl1:
			inc b
			push bc
			push hl
			call ntc_irq_jp			; (the handler runs on the real stack)
			pop hl
			pop bc
			djnz ntc_irq_cl
			pop bc
ntc_irq_nocl:
			ld hl, (ntc_irqhl)
			ex af, af'
			ei
			reti					; (reti, not ret: with ntc_zxn_inthold the Next's interrupt controller
ntc_irq_jp:						; takes it as the end of the interrupt - in IM 1 the same as ret)
			jp (hl)
ntc_irqn:		db 1			; the ticks this interrupt counted (1-6)

ntc_rg111_e:
			IF ($ < 49152) && (ntc_rg112_e - ntc_rg112 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg112_e - ntc_rg112 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg112_e - ntc_rg112 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg112:
;## ntc_plat_exit ntc_plat_data
; ------------------------------------------------------------
; ntc_plat_exit - the end: interrupts off, a soft reset (NextReg 2 bit 0) -
; back to NextZXOS (a NEX file has no caller to return to)
; ------------------------------------------------------------
ntc_plat_exit:
			di
			ld bc, #243B
			ld a, #02
			out (c), a
			inc b
			ld a, 1
			out (c), a
ntc_ex_wait:
			jr ntc_ex_wait

ntc_rg112_e:
			IF ($ < 49152) && (ntc_rg113_e - ntc_rg113 + $ > 48640)	; fwdref-ok
			ds 49152 - $		; Option Memory Reserved #BE00-#BFFF: round it
			ENDIF
			IF ($ < 62464) && (ntc_rg113_e - ntc_rg113 + $ > 57344)	; fwdref-ok
			ds 62464 - $		; Option Memory Reserved #E000-#F3FF: round it
			ENDIF
			IF ($ < 65536) && (ntc_rg113_e - ntc_rg113 + $ > 64768)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #FD00 (Option Memory Reserved #FD00-#FFFF is the top of memory)"
ntc_oom = 1		; (said once: the parts after this one reach it too)
			ENDIF
ntc_rg113:
;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the program's arrays and the Memory class's heap in
; main memory must not use. ZXN_MEMTOP (the compiler's): #BA00 with the FileSystem or Loader
; class (their DOS area #BA00-#BDFF, then the stack to #C000), #BE00 without (20261118-1). A
; program that runs on over the stack has its arrays in #C000-#FFFF, where the build has
; already checked them against what is there: the top is then #FD00 (the start-up stub).
; (20261118-1: it was #BA00 always, so such a program stopped at its start with GURU 001.)
; Called on the real stack (call / ret).
ntc_plat_memtop:
			IF ntc_free > #C000		; fwdref-ok
			ld hl, #FD00
			ELSE
			ld hl, ZXN_MEMTOP
			ENDIF
			ret


ntc_pgloaded:	db 4		; the pages taken from the start (Loaded n, Option SaveNex, Option Memory Reserve Pages, the program's own: 0 1 2 5): how many, then the pages
			dw 0, 1, 2, 5
ntc_rg113_e:
ntc_end:				; the end of the program (and of its file)
